51	// newOnboardingRungDeps wires the rung probes to their real backends: agent
52	// hook detection, the stored auth context (offline — deliberately not
53	// RefreshedLoginToken, which can hit the network), origin parsing, the
54	// control-plane mirror list, and local agent-transcript discovery.
55	func newOnboardingRungDeps() onboardingRungDeps {
