79	// already has a mirror. Owner/repo arrive lowercased from the mirror rung.
80	func probeRepoMirrored(ctx context.Context, owner, repo string) (bool, error) {
81		ctx, cancel := context.WithTimeout(ctx, mirrorProbeTimeout)
82		defer cancel()
83		client, err := coreapi.New()
84		if err != nil {
85			return false, err
86		}
87		out, err := client.ListAvailableMirrors(ctx, coreapi.ListAvailableMirrorsParams{
88			Owner: coreapi.NewOptString(owner),
89		})
90		if err != nil {
91			return false, err
92		}
93		for _, m := range out.Available {
94			if strings.EqualFold(m.Owner, owner) && strings.EqualFold(m.Repo, repo) {
95				return m.Status == coreapi.AvailableMirrorStatusMirrored, nil
96			}
97		}
98		return false, nil
99	}
