101	// discoverAgentImports reports, per registered importer, how much local
102	// transcript history exists for this repo and how much of it has never been
103	// imported. Discovery is file globbing; only agents with discoverable
104	// sessions pay for the dry-run (which opens the checkpoint store to detect
105	// already-imported turns). Local-only, best-effort per agent.
106	func discoverAgentImports(ctx context.Context) ([]agentImportStatus, error) {
107		repoRoot, err := paths.WorktreeRoot(ctx)
108		if err != nil {
109			return nil, fmt.Errorf("resolve worktree root: %w", err)
110		}
111		now := time.Now()
112		var statuses []agentImportStatus
113		for _, imp := range agentimport.All() {
114			files, discoverErr := imp.Discover(repoRoot, "", now, nil)
115			if discoverErr != nil || len(files) == 0 {
116				continue
117			}
118			repo, openErr := openRepository(ctx)
119			if openErr != nil {
120				return nil, openErr
121			}
122			res, runErr := agentimport.Run(ctx, repo, imp, agentimport.Options{
123				RepoRoot: repoRoot, Now: now, DryRun: true,
124			})
125			_ = repo.Close()
126			if runErr != nil {
