12		"github.com/entireio/cli/cmd/entire/cli/onboarding"
13	)
14	
15	// onboardingSetupMode is the answer to enable's single consent prompt.
16	type onboardingSetupMode int
17	
18	const (
19		// setupModeAll runs every missing rung back-to-back without further questions.
20		setupModeAll onboardingSetupMode = iota
21		// setupModeStepByStep confirms each missing rung individually.
22		setupModeStepByStep
23		// setupModeSkip leaves everything local and prints the run-later checklist.
24		setupModeSkip
25	)
26	
27	// onboardingOfferRunner drives the connect rungs at the end of `entire
28	// enable`: one consent prompt, then offers for whatever is missing, then the
29	// closing checklist. Rung state is recomputed before each offer, so a login
30	// completed in this pass unblocks the mirror rung in the same pass, and a
31	// rung finished out-of-band is never re-offered — which is also what makes
32	// re-running `entire enable` the resume path after an interrupted setup.
33	// All fields are seams; newOnboardingOfferRunner wires production behavior.
34	type onboardingOfferRunner struct {
35		deps        onboardingRungDeps
36		offerFns    map[string]func(ctx context.Context) error
37		canPrompt   func() bool
38		promptMode  func(missing []onboarding.Result) (onboardingSetupMode, error)
39		confirmRung func(r onboarding.Result) (bool, error)
40		styles      func(w io.Writer) statusStyles
41	}
42	
43	func (r onboardingOfferRunner) run(ctx context.Context, w io.Writer) {
44		ladder := onboardingLadder(r.deps)
45		results := ladder.Checks(ctx)
46	
47		if actionable := r.offerable(results); len(actionable) > 0 && r.canPrompt() {
48			mode, err := r.promptMode(actionable)
49			if err != nil {
50				// Cancelling the consent prompt (Ctrl-C) behaves like skip: enable
51				// has already succeeded, so fall through to the checklist, whose
52				// hints are the resume path.
53				mode = setupModeSkip
54			}
55			if mode != setupModeSkip {
56				r.runOffers(ctx, w, ladder, mode)
57				results = ladder.Checks(ctx)
58			}
59		}
60	
61		fmt.Fprint(w, r.renderChecklist(w, results))
62	}
63	
64	// offerable filters the remaining work down to rungs this runner can act on:
65	// missing or blocked, with an offer wired. Blocked rungs count because an
66	// earlier offer in the same pass (login) can unblock them.
67	func (r onboardingOfferRunner) offerable(results []onboarding.Result) []onboarding.Result {
68		var actionable []onboarding.Result
69		for _, res := range onboarding.Missing(results) {
70			if r.offerFns[res.Rung.Key] != nil {
71				actionable = append(actionable, res)
72			}
73		}
74		return actionable
75	}
76	
77	// runOffers walks the ladder in order, re-checking each rung immediately
78	// before its offer. Offers are best-effort: a failure prints a notice and the
79	// closing checklist keeps the retry hint, but enable never fails.
80	func (r onboardingOfferRunner) runOffers(ctx context.Context, w io.Writer, ladder onboarding.Ladder, mode onboardingSetupMode) {
81		for _, rung := range ladder {
82			offer := r.offerFns[rung.Key]
83			if offer == nil {
84				continue
85			}
86			check := rung.Check(ctx)
87			if check.State != onboarding.StateMissing {
88				continue
89			}
90			if mode == setupModeStepByStep {
91				accepted, err := r.confirmRung(onboarding.Result{Rung: rung, Check: check})
92				if err != nil || !accepted {
93					continue
94				}
95			}
96			if err := offer(ctx); err != nil {
97				fmt.Fprintf(w, "  %s setup didn't complete: %v\n", rung.Title, err)
98			}
99		}
100	}
101	
102	func (r onboardingOfferRunner) renderChecklist(w io.Writer, results []onboarding.Result) string {
103		sty := r.styles(w)
104		var b strings.Builder
105		b.WriteString(renderOnboardingChecklist(results, sty))
106		// One "run later" line per unique command, in ladder order — a blocked
107		// rung whose fix is another rung's command (mirror needs login) must not
108		// repeat it.
109		seen := map[string]bool{}
110		for _, res := range onboarding.Missing(results) {
111			if res.Check.Hint == "" || seen[res.Check.Hint] {
112				continue
113			}
114			seen[res.Check.Hint] = true
115			fmt.Fprintf(&b, "  run later: %s\n", sty.render(sty.cyan, res.Check.Hint))
116		}
117		return b.String()
118	}
119	
120	// runEnableOnboarding runs the connect ladder at the end of `entire enable`.
121	// assumeYes (--yes) forces the non-interactive contract: no prompts and no
122	// implicit login/mirror — the checklist hints carry the follow-up commands.
123	// Best-effort by design: onboarding output problems never fail enable.
124	var runEnableOnboarding = func(ctx context.Context, w io.Writer, assumeYes bool) {
125		r := newOnboardingOfferRunner(w)
126		if assumeYes {
127			r.canPrompt = func() bool { return false }
128		}
129		fmt.Fprintln(w)
130		r.run(ctx, w)
131	}
132	
133	// newOnboardingOfferRunner wires the production runner: real rung probes,
134	// the browser login and mirror-create offers, and huh-based prompts.
135	func newOnboardingOfferRunner(errW io.Writer) onboardingOfferRunner {
136		deps := newOnboardingRungDeps()
137		return onboardingOfferRunner{
138			deps: deps,
139			offerFns: map[string]func(ctx context.Context) error{
140				onboarding.KeyAuth:   func(ctx context.Context) error { return runOnboardingLogin(ctx, errW) },
141				onboarding.KeyMirror: func(ctx context.Context) error { return runOnboardingMirrorCreate(ctx, errW, deps) },
142			},
143			canPrompt:   interactive.CanPromptInteractively,
144			promptMode:  promptOnboardingSetupMode,
145			confirmRung: confirmOnboardingRung,
146			styles:      newStatusStyles,
147		}
148	}
149	
150	// promptOnboardingSetupMode is enable's single consent prompt, summarizing
151	// what "finish setup" will do from the missing rungs' titles.
152	func promptOnboardingSetupMode(missing []onboarding.Result) (onboardingSetupMode, error) {
153		summary := onboardingSetupSummary(missing)
154		mode := setupModeAll
155		form := NewAccessibleForm(
156			huh.NewGroup(
157				huh.NewSelect[onboardingSetupMode]().
158					Title("Finish setup?").
159					Description(summary).
160					Options(
161						huh.NewOption("Yes, set up everything (recommended)", setupModeAll),
162						huh.NewOption("Choose step by step", setupModeStepByStep),
163						huh.NewOption("Skip — local tracking only", setupModeSkip),
164					).
165					Value(&mode),
166			),
167		)
168		if err := form.Run(); err != nil {
169			return setupModeSkip, fmt.Errorf("setup consent prompt: %w", err)
170		}
171		return mode, nil
172	}
173	
174	// onboardingSetupSummary describes what the fast path will do, e.g.
175	// "Logs in to entire.io and mirrors github.com/acme/api so sessions and
176	// commits appear in the web UI."
177	func onboardingSetupSummary(missing []onboarding.Result) string {
178		steps := make([]string, 0, len(missing))
179		for _, r := range missing {
180			switch r.Rung.Key {
181			case onboarding.KeyAuth:
182				steps = append(steps, "logs in to entire.io")
183			case onboarding.KeyMirror:
