200		}
201		summary += summarySb188.String()
202		// Capitalize the first step: summaries are full sentences in the prompt.
203		return string(summary[0]-'a'+'A') + summary[1:] + " so your work shows up in the web UI."
204	}
205	
206	func confirmOnboardingRung(r onboarding.Result) (bool, error) {
207		title := r.Rung.Title
