19	// runOnboardingLogin is the auth rung's offer: the same browser-first login
20	// `entire login` runs, with default flags (standard login server, no device
21	// mode unless the environment forces it). w is enable's output writer.
22	func runOnboardingLogin(ctx context.Context, w io.Writer) error {
23		loginServer, err := parseLoginServer(api.DefaultAuthBaseURL)
24		if err != nil {
25			return fmt.Errorf("resolve login server: %w", err)
26		}
27		client := auth.NewClient(loginServer, nil, false)
28		startBrowser := func(ctx context.Context) (browserAuthFlow, error) {
29			return client.StartBrowserAuth(ctx)
30		}
31		return runLoginAuto(ctx, w, w, client, startBrowser, openBrowser, loginFlowFacts{
32			canPrompt:  interactive.CanPromptInteractively(),
33			sshSession: isSSHSession(),
34		})
35	}
36	
37	// runOnboardingImport is the import rung's offer, composing the enable-time
38	// import machinery from PR #1595: agent-scoped discovery, the optional
39	// per-agent picker, and best-effort per-agent imports (checkpoint policy and
40	// redaction config are enforced inside runSelectedImports). granular=true
41	// (step-by-step mode) shows the picker — Import/Skip confirm for one agent,
42	// multi-select for several, empty selection skips. granular=false imports
43	// everything eligible: the "set up everything" and --yes paths, where consent
44	// was already given.
45	func runOnboardingImport(ctx context.Context, w io.Writer, granular bool) error {
46		repoRoot, err := paths.WorktreeRoot(ctx)
47		if err != nil {
48			return fmt.Errorf("resolve worktree root: %w", err)
49		}
50		eligible := sessionImportDiscover(ctx, installedImportAgents(ctx), repoRoot)
51		if len(eligible) == 0 {
52			return nil
53		}
54		selected := eligible
55		if granular {
56			selected, err = sessionImportPrompt(ctx, w, eligible)
57			if err != nil {
58				return fmt.Errorf("import selection: %w", err)
59			}
60			if len(selected) == 0 {
61				return nil
62			}
63		}
64		sessionImportRun(ctx, w, repoRoot, selected)
65		return nil
66	}
67	
68	// installedImportAgents resolves the agents whose hooks are installed — the
69	// ladder's import scope. (#1595 scoped to the just-selected agents; the
70	// ladder runs on resume paths too, where "installed" is the equivalent set.)
71	func installedImportAgents(ctx context.Context) []agent.Agent {
72		names := GetAgentsWithHooksInstalled(ctx)
73		out := make([]agent.Agent, 0, len(names))
74		for _, name := range names {
75			if ag, err := agent.Get(name); err == nil {
76				out = append(out, ag)
77			}
78		}
79		return out
80	}
81	
82	// runOnboardingMirrorCreate is the mirror rung's offer: register a mirror for
83	// the origin repo on the default cluster and return once placement is
84	// confirmed. The initial clone continues server-side (`--no-wait` semantics),
85	// so enable never blocks on a large repo's clone.
86	func runOnboardingMirrorCreate(ctx context.Context, errW io.Writer, deps onboardingRungDeps) error {
87		forge, owner, repo, err := deps.resolveOrigin(ctx)
88		if err != nil {
89			return fmt.Errorf("resolve origin: %w", err)
90		}
91		if forge != "gh" {
92			return errors.New("origin is not a GitHub repository")
93		}
94		owner, repo = githubSlug(owner, repo)
95		client, err := coreapi.NewForCluster(ctx, defaultClusterHost)
96		if err != nil {
97			return fmt.Errorf("connect to %s: %w", defaultClusterHost, err)
98		}
99		spin := startSpinner(errW, fmt.Sprintf("Mirroring %s/%s to %s", owner, repo, defaultClusterHost))
100		outcome, err := createAndAwaitMirror(ctx, client, owner, repo, defaultClusterHost,
101			true /* noWait: clone continues in the background */, 0, nil, nil)
102		spin(err == nil)
103		if err != nil {
104			return err
105		}
106		return finalizeMirrorOffer(errW, outcome, owner+"/"+repo, func(slug string) {
107			// Write-through: the placement is registered, so the probe cache can
108			// say "mirrored" immediately instead of waiting for the server-side
109			// clone to surface in the available-mirrors list.
110			defaultMirrorProbeCache().put(slug, true, time.Now())
111		})
112	}
113	
114	// finalizeMirrorOffer turns a nil-error createAndAwaitMirror outcome into the
115	// offer's result. A suspended placement returns nil error from the create
116	// path but will never serve — report it like `entire repo mirror create`
117	// does, return an error so the rung keeps its retry hint, and skip the
118	// cache write-through that would otherwise claim "mirrored" for the TTL.
119	func finalizeMirrorOffer(w io.Writer, outcome mirrorCreateOutcome, slug string, cachePut func(slug string)) error {
120		created := outcome.created
121		if created == nil {
122			return errors.New("mirror placement not registered")
123		}
124		if created.Suspended {
125			fmt.Fprintln(w, "  WARNING: this mirror has been suspended by an admin and won't be usable.")
126			return errMirrorSuspended
127		}
128		if !created.Empty {
129			fmt.Fprintln(w, "  Mirror registered — the initial clone continues in the background.")
130		}
131		cachePut(slug)
132		return nil
133	}

